# Regression gate against funresMech 1.1.0 (as released on CRAN).
#
# The default model (Gamma search times, Lognormal handling times) must
# reproduce EXACTLY, with the same seeds, the simulated counts and the
# simulated negative log-likelihood of version 1.1.0. Reference values are in
# fixtures/golden_1.1.0.rds (generated by fixtures/make_golden.R).
#
# The first likelihood case is the anchor against the supplementary code of
# Okuyama (2026): D3, z = 2.5, 3000 simulated trials, seed 88, no saturation
# cut-off -> NLL = 132.04994217 in both implementations.

golden <- readRDS(test_path("fixtures", "golden_1.1.0.rds"))
d2 <- read.csv(test_path("fixtures", "D2.csv"))
d3 <- read.csv(test_path("fixtures", "D3.csv"))

test_that("anchor: NLL of D3 equals the value of the supplementary code of the method (132.04994217)", {
  set.seed(88)
  nll <- funresMech:::negloglik_fixed_z(c(0.012, 0.626, 0.902, 0.542),
                                        z_fixed = 2.5, data_spp = d3, T = 24,
                                        n_sim = 3000, stop_saturated = FALSE)
  expect_equal(sprintf("%.8f", nll), "132.04994217")
})

test_that("engine reproduces the simulated counts of 1.1.0 exactly", {
  for (cs in golden$engine) {
    for (cut in c(TRUE, FALSE)) {
      set.seed(cs$seed)
      out <- funresMech:::sim_engine_cpp(cs$H, cs$a, cs$h, cs$z, cs$k,
                                            cs$s, cs$T, cs$n, cut)
      ref <- if (cut) cs$out_cut else cs$out_nocut
      expect_identical(as.integer(out), as.integer(ref))
    }
  }
})

test_that("simulated likelihood reproduces the NLL of 1.1.0 exactly", {
  for (cs in golden$nll) {
    d <- if (cs$data == "D2") d2 else d3
    set.seed(cs$seed)
    nll <- funresMech:::negloglik_fixed_z(cs$par, z_fixed = cs$z, data_spp = d,
                                          T = golden$T_exp, n_sim = cs$n_sim,
                                          stop_saturated = cs$cut)
    # Integer counts are compared exactly above; the NLL is a sum of logs and
    # may differ in the last bits between compilers/math libraries (Windows
    # vs Linux), hence the tiny tolerance.
    expect_equal(nll, cs$nll, tolerance = 1e-10)
  }
})
